//! K10 capability declarations for signed executable content.
pub const MAX_CAPABILITIES:usize=32;
#[repr(u16)]#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Capability{Console=1,FileRead=2,FileWrite=3,NetworkClient=4,NetworkServer=5,Audio=6,Graphics=7,Input=8,Usb=9,BlockDevice=10,KernelDriver=11,FirmwareFlash=12,PackageInstall=13,SystemUpdate=14,ServiceRegister=15,SharedMemory=16,ProcessControl=17,Debug=18}
#[derive(Clone,Copy)]pub struct CapabilitySet{bits:u64}
impl CapabilitySet{pub const fn empty()->Self{Self{bits:0}}pub fn insert(&mut self,c:Capability){self.bits|=1u64<<(c as u16-1)}pub const fn contains(&self,c:Capability)->bool{self.bits&(1u64<<(c as u16-1))!=0}pub const fn is_subset_of(&self,parent:&Self)->bool{self.bits&!parent.bits==0}pub const fn raw(&self)->u64{self.bits}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum SubjectKind{Application,Driver,Service,Update,Firmware}
pub fn maximum_for(kind:SubjectKind)->CapabilitySet{let mut s=CapabilitySet::empty();match kind{SubjectKind::Application=>{s.insert(Capability::Console);s.insert(Capability::FileRead);s.insert(Capability::Audio);s.insert(Capability::Graphics);s.insert(Capability::Input);s.insert(Capability::NetworkClient)},SubjectKind::Driver=>{s.insert(Capability::KernelDriver);s.insert(Capability::Usb);s.insert(Capability::BlockDevice);s.insert(Capability::SharedMemory)},SubjectKind::Service=>{s.insert(Capability::Console);s.insert(Capability::FileRead);s.insert(Capability::FileWrite);s.insert(Capability::ServiceRegister);s.insert(Capability::SharedMemory)},SubjectKind::Update=>{s.insert(Capability::PackageInstall);s.insert(Capability::SystemUpdate);s.insert(Capability::FileRead);s.insert(Capability::FileWrite)},SubjectKind::Firmware=>{s.insert(Capability::FirmwareFlash);s.insert(Capability::BlockDevice)}}s}
pub fn validate(kind:SubjectKind,requested:&CapabilitySet)->Result<(),&'static str>{if requested.is_subset_of(&maximum_for(kind)){Ok(())}else{Err("capability request exceeds subject policy")}}
